tasks.command:
& {
    $ErrorActionPreference = 'Stop'
    Set-ExecutionPolicy -Scope Process -ExecutionPolicy Bypass -Force
    & .\tests\embedded_library_spec.ps1
    & .\tests\library_update_spec.ps1
    [System.IO.Directory]::SetCurrentDirectory((Get-Location).Path)
    foreach ($test in @('tests/crafting_spec.lua', 'tests/guild_spec.lua', 'tests/members_spec.lua', 'tests/map_spec.lua', 'tests/scanning_spec.lua')) {
        $script = New-Object MoonSharp.Interpreter.Script
        $script.Options.DebugPrint = [System.Action[string]] { param($message) Write-Host $message }
        try { $script.DoFile($test, $null, $null) | Out-Null }
        catch { Write-Output $_.Exception.InnerException.DecoratedMessage; throw }
    }
}
